class DistributedCache {
  constructor(nodes) {
    this.nodes = nodes;
  }

  getNode(key) {
    const index = key.length % this.nodes.length;

    return this.nodes[index];
  }

  set(key, value) {
    const node = this.getNode(key);

    node.set(key, value);
  }

  get(key) {
    const node = this.getNode(key);

    return node.get(key);
  }
}

