class JobQueue {
  constructor() {
    this.jobs = [];
  }

  add(job, priority) {
    this.jobs.push({ job, priority });

    this.jobs.sort((a, b) => {
      return b.priority - a.priority;
    });
  }

  process() {
    while (this.jobs.length > 0) {
      const currentJob = this.jobs.shift();

      currentJob.job();
    }
  }
}

