class SearchIndex {
  constructor() {
    this.index = {};
  }

  add(documentId, content) {
    const words = content.toLowerCase().split(' ');

    words.forEach((word) => {
      if (!this.index[word]) {
        this.index[word] = new Set();
      }

      this.index[word].add(documentId);
    });
  }

  search(word) {
    return [...(this.index[word.toLowerCase()] || [])];
  }
}

