class MessageBroker {
  constructor() {
    this.queue = [];
  }

  publish(message) {
    this.queue.push({
      message,
      acknowledged: false
    });
  }

  consume() {
    const item = this.queue.find((entry) => {
      return entry.acknowledged === false;
    });

    if (!item) {
      return;
    }

    item.acknowledged = true;

    return item.message;
  }
}

