class CircuitBreaker {
  constructor(limit) {
    this.limit = limit;
    this.failures = 0;
    this.open = false;
  }

  async execute(action) {
    if (this.open) {
      console.log('Circuit is open');

      return;
    }

    try {
      const result = await action();

      this.failures = 0;

      return result;
    } catch (error) {
      this.failures++;

      if (this.failures >= this.limit) {
        this.open = true;
      }

      console.log('Request failed');
    }
  }
}

