class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate;

    setInterval(() => {
      this.tokens = Math.min(
        this.capacity,
        this.tokens + this.refillRate
      );
    }, 1000);
  }

  consume() {
    if (this.tokens <= 0) {
      console.log('Rate limit exceeded');

      return false;
    }

    this.tokens--;

    console.log('Request accepted');

    return true;
  }
}

const limiter = new TokenBucket(5, 1);

limiter.consume();

class LockManager {
  constructor() {
    this.locks = new Set();
  }

  acquire(resource) {
    if (this.locks.has(resource)) {
      console.log('Resource is locked');

      return false;
    }

