const createAsyncAction = (types) => {
  return (...args) => {
    return async (dispatch) => {
      dispatch({ type: types.pending });
      try {
        const result = await args[0]();
        dispatch({ type: types.success, payload: result });
        return result;
      } catch (error) {
        dispatch({ type: types.failure, payload: error.message });
        throw error;
      }
    };
  };
};

