class Model {
  constructor() {
    this.data = {};
    this.listeners = [];
  }

  get(key) { return this.data[key]; }
  set(key, value) {
    this.data[key] = value;
    this.notify();
  }

  subscribe(listener) {
    this.listeners.push(listener);
  }

  notify() {
    this.listeners.forEach(fn => fn(this.data));
  }
}

